package com.beeboee.magnot.item;
import com.beeboee.magnot.network.MagnotNetwork;import com.beeboee.magnot.region.*;import com.beeboee.magnot.server.FerrousEffects;import net.minecraft.core.BlockPos;import net.minecraft.nbt.CompoundTag;import net.minecraft.network.chat.Component;import net.minecraft.server.level.ServerLevel;import net.minecraft.util.Mth;import net.minecraft.world.*;import net.minecraft.world.entity.Entity;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.*;import net.minecraft.world.item.context.UseOnContext;import net.minecraft.world.level.Level;import java.util.*;
public final class FerrousTubeItem extends Item{public static final int MAX_REGION_AXIS_LENGTH=25;private static final int LIMIT=24;private static final String H="MagnotHasFirstCorner",X="MagnotFirstX",Y="MagnotFirstY",Z="MagnotFirstZ",D="MagnotFirstDimension";public FerrousTubeItem(Properties p){super(p);}@Override public InteractionResult useOn(UseOnContext c){Level level=c.getLevel();Player p=c.getPlayer();ItemStack stack=c.getItemInHand();if(p==null)return InteractionResult.PASS;if(level.isClientSide)return InteractionResult.SUCCESS;if(!(level instanceof ServerLevel s))return InteractionResult.PASS;if(p.isShiftKeyDown()){if(getFirstCorner(stack).isPresent()){clear(stack);p.displayClientMessage(Component.translatable("message.magnot.selection_cleared"),true);}return InteractionResult.SUCCESS;}BlockPos clicked=c.getClickedPos();Optional<BlockPos> first=getFirstCorner(stack);String dimension=s.dimension().location().toString();if(first.isEmpty()||!dimension.equals(getDimension(stack))){set(stack,clicked,dimension);FerrousEffects.firstCorner(s,clicked);p.displayClientMessage(Component.translatable("message.magnot.first_corner"),true);return InteractionResult.SUCCESS;}BlockPos second=clampToRegionLimit(first.get(),clicked);FerrousRegion r=FerrousRegion.fromCorners(UUID.randomUUID(),first.get(),second);FerrousRegionSavedData.get(s).addRegion(r);MagnotNetwork.syncDimension(s);clear(stack);p.displayClientMessage(Component.translatable("message.magnot.region_created"),true);FerrousEffects.confirm(s,second,r);if(!p.getAbilities().instabuild)stack.hurtAndBreak(2,p,q->q.broadcastBreakEvent(c.getHand()));return InteractionResult.SUCCESS;}@Override public void inventoryTick(ItemStack stack,Level level,Entity e,int slot,boolean selected){if(!level.isClientSide&&!selected&&getFirstCorner(stack).isPresent())clear(stack);}public static Optional<BlockPos> getFirstCorner(ItemStack s){CompoundTag t=s.getTag();return t==null||!t.getBoolean(H)?Optional.empty():Optional.of(new BlockPos(t.getInt(X),t.getInt(Y),t.getInt(Z)));}public static BlockPos clampToRegionLimit(BlockPos a,BlockPos b){return new BlockPos(a.getX()+Mth.clamp(b.getX()-a.getX(),-LIMIT,LIMIT),a.getY()+Mth.clamp(b.getY()-a.getY(),-LIMIT,LIMIT),a.getZ()+Mth.clamp(b.getZ()-a.getZ(),-LIMIT,LIMIT));}public static boolean exceedsRegionLimit(BlockPos a,BlockPos b){return Math.abs(b.getX()-a.getX())>=25||Math.abs(b.getY()-a.getY())>=25||Math.abs(b.getZ()-a.getZ())>=25;}private static String getDimension(ItemStack s){return s.getTag()==null?"":s.getTag().getString(D);}private static void set(ItemStack s,BlockPos p,String d){CompoundTag t=s.getOrCreateTag();t.putBoolean(H,true);t.putInt(X,p.getX());t.putInt(Y,p.getY());t.putInt(Z,p.getZ());t.putString(D,d);}private static void clear(ItemStack s){CompoundTag t=s.getOrCreateTag();t.remove(H);t.remove(X);t.remove(Y);t.remove(Z);t.remove(D);}}
